from pathlib import Path
p=Path('build_d9.py');t=p.read_text()
def rep(a,b):
    global t
    assert a in t,('MISSING',a[:90]);t=t.replace(a,b)
rep("PIV_OFF_Y=45.0","PIV_OFF_Y=25.0                                      # port 1 then sits 76 mm from the axis, port 2 86; enough for a 70-mm disc and its skirt")
rep("SHAFT_D=75.0;SHAFT_BORE=50.0                        # hollow: cable route and material","SHAFT_D=50.0;SHAFT_BORE=30.0                        # hollow, for material; nothing routes through it")
rep("TH_D=72.0;TH_P=3.0;TH_CORE=69.7                     # shallow flat-crested trapezoid, 1.15-mm depth","TH_D=47.0;TH_P=3.0;TH_CORE=44.7                     # shallow flat-crested trapezoid, 1.15-mm depth")
rep("SH_FACE=-52.5;SH_T=7.0;SH_OD=90.0                   # stationary shoulder: the clamping face","SH_FACE=-40.0;SH_T=7.0;SH_OD=70.0                   # stationary shoulder: the clamping face, just outboard of the socket flange")
rep("ARM_T=13.0;ARM_OD=90.0;ARM_BORE=75.5                # 0.25-mm radial running fit on the journal","ARM_T=10.0;ARM_OD=70.0;ARM_BORE=50.5                # 0.25-mm radial running fit on the journal")
rep("CAM_T=14.0;CAM_X0=ARM_X0-CAM_T;CAM_BORE=75.5;CAM_HUB_R=46.0   # hub 2 mm inside the retracted sleeve","CAM_T=10.0;CAM_X0=ARM_X0-CAM_T;CAM_BORE=50.5;CAM_HUB_R=35.0   # hub inside the retracted sleeve")
rep("WSH_T=2.5;WSH_OD=100.0;WSH_ID=75.6;WSH_X0=CAM_X0-WSH_T","WSH_T=2.5;WSH_OD=75.0;WSH_ID=50.6;WSH_X0=CAM_X0-WSH_T")
rep("NUT_T=12.0;NUT_OD=100.0;NUT_X=WSH_X0-NUT_T;NUT_FLUTES=20","NUT_T=9.0;NUT_OD=72.0;NUT_X=WSH_X0-NUT_T;NUT_FLUTES=16")
rep("JRN_X0=WSH_X0-0.5;THR_X0=NUT_X-7.0                  # journal covers disc, cam and washer; 7 mm of thread spare outboard of the nut","JRN_X0=WSH_X0-0.5;THR_X0=NUT_X-4.0                  # journal covers disc, cam and washer; 4 mm of thread spare outboard of the nut")
rep("RING_X=9.5;RING_T=6.0;RING_OD=100.0;RING_ID=78.0","RING_X=9.5;RING_T=6.0;RING_OD=80.0;RING_ID=56.0")
rep("TONGUE_END=BZ+101.0","TONGUE_END=BZ+83.5")
rep("_sl0=BZ+60.0;_sl1=TONGUE_END-4.0","_sl0=BZ+46.0;_sl1=TONGUE_END-4.0")
rep("SLV_X0=TONGUE_X0-2.8;SLV_W=TONGUE_T+0.8+2.8+2.4","SLV_X0=TONGUE_X0-2.8;SLV_W=TONGUE_T+0.8+2.8+2.0")
rep("tip_z=BZ+138.0;tip_y=BY                             # modelled mid-travel pose\nsleeve_z=tip_z-75.0","tip_z=BZ+113.0;tip_y=BY                             # modelled mid-travel pose\nsleeve_z=tip_z-66.0")
rep("for zz in (tip_z-67.0,tip_z-49.0):","for zz in (tip_z-58.0,tip_z-44.0):")
rep("PAD_LAT=34.0;PAD_RAD=46.0                           # rotor pocket centre: 34 mm lateral (-Y at the modelled pose), 46 mm inboard of the tip","PAD_LAT=34.0;PAD_RAD=39.0                           # rotor pocket centre: 34 mm lateral (-Y at the modelled pose), 39 mm inboard of the tip")
rep("CAM_R0=72.0;CAM_B=1.1;CAM_ARC=24.0;CAM_CUT=3.0;CAM_GAP=0.5","CAM_R0=58.0;CAM_B=1.2;CAM_ARC=24.0;CAM_CUT=3.0;CAM_GAP=0.5")
p.write_text(t)
c=Path('audit/clamp_views.py');u=c.read_text()
u=u.replace("BY,BZ=CL['pivot_axis_yz_mm'];tip_z=BZ+138.0;tip_y=BY","BY,BZ=CL['pivot_axis_yz_mm'];tip_z=BZ+113.0;tip_y=BY")
u=u.replace("zoom=box(-104,BY-1,BZ+28,56,60,22)","zoom=box(-82,BY-1,BZ+15,52,60,20)")
c.write_text(u);print('ok')
